return-response.set-body:
@{
                var issuer = "{{mcp-facade-issuer}}";
                var useFacades = "{{mcp-facades-enabled}}" == "true";
                var idp = "{{mcp-idp-authority}}/oauth2/v2.0";
                var doc = new JObject(
                    new JProperty("issuer", issuer),
                    new JProperty("authorization_endpoint", useFacades ? issuer + "/authorize" : idp + "/authorize"),
                    new JProperty("token_endpoint", useFacades ? issuer + "/token" : idp + "/token"),
                    new JProperty("response_types_supported", new JArray("code")),
                    new JProperty("response_modes_supported", new JArray("query")),
                    new JProperty("grant_types_supported", new JArray("authorization_code", "refresh_token")),
                    new JProperty("code_challenge_methods_supported", new JArray("S256")),
                    new JProperty("token_endpoint_auth_methods_supported", new JArray("none")),
                    new JProperty("scopes_supported", new JArray("mcp.tools", "offline_access")),
                    new JProperty("service_documentation", "{{mcp-docs-base-url}}/auth")
                );
                if ("{{mcp-registration-enabled}}" == "true")
                {
                    doc["registration_endpoint"] = issuer + "/register";
                }
                return doc.ToString();
            }
